"use client"

import * as React from "react"

// ==========================================
// 1. Cascade Dashboard (Infinite, Responsive, Light/Dark Mode)
// ==========================================
const shimmerCSS = `
  @keyframes cascadeShimmer {
    0%, 100% { opacity: 0.25; }
    50% { opacity: 1; }
  }
  @keyframes cascadeFadeUp {
    from { opacity: 0; transform: translateY(8px); }
    to { opacity: 1; transform: translateY(0); }
  }
`

function ShimmerBlock({ width, height, delay, rounded = 4 }: { width: number | string; height: number; delay: number; rounded?: number }) {
    return (
        <span
            style={{
                background: "var(--cascade-skeleton-hi)",
                borderRadius: rounded,
                display: "block",
                height,
                width,
                animation: `cascadeShimmer 1.5s ease-in-out infinite`,
                animationDelay: `${delay}ms`
            }}
        />
    )
}

export function CascadeDashboard() {
    const [loaded, setLoaded] = React.useState(false)
    const [cycle, setCycle] = React.useState(0)

    // Infinite loop timer: loads for 3.5s, shows ready state for 2.5s, then loops back
    React.useEffect(() => {
        let isMounted = true
        let activeTimer: number | undefined

        const runCycle = () => {
            setLoaded(false)
            activeTimer = window.setTimeout(() => {
                if (!isMounted) return
                setLoaded(true)
                activeTimer = window.setTimeout(() => {
                    if (!isMounted) return
                    runCycle()
                }, 2500) // Duration to stay in "Dashboard Ready" state before restarting
            }, 3500) // Duration of skeleton loading state
        }

        runCycle()
        return () => {
            isMounted = false
            if (activeTimer !== undefined) {
                window.clearTimeout(activeTimer)
            }
        }
    }, [cycle])

    return (
        <main
            className="cascade-dashboard"
            style={{
                background: "var(--cascade-page)",
                borderRadius: 12,
                border: "1px solid var(--cascade-line)",
                boxShadow: "var(--cascade-shadow)",
                color: "var(--cascade-text)",
                display: "flex",
                flexDirection: "column",
                fontFamily: "Inter, ui-sans-serif, system-ui",
                minHeight: 420,
                height: "auto",
                overflow: "hidden",
                position: "relative",
                width: "100%",
                maxWidth: 720,
                boxSizing: "border-box",
            }}
        >
            <style>{`
                .cascade-dashboard {
                    --cascade-page: #f4f4f6;
                    --cascade-panel: #ffffff;
                    --cascade-line: rgba(0, 0, 0, 0.08);
                    --cascade-skeleton-hi: rgba(0, 0, 0, 0.12);
                    --cascade-text: #1c1c1f;
                    --cascade-subtext: rgba(0, 0, 0, 0.55);
                    --cascade-shadow: 0 20px 40px rgba(0, 0, 0, 0.06);
                }
                .dark .cascade-dashboard,
                [data-theme="dark"] .cascade-dashboard {
                    --cascade-page: #1c1c1f;
                    --cascade-panel: #26262a;
                    --cascade-line: rgba(255, 255, 255, 0.08);
                    --cascade-skeleton-hi: rgba(255, 255, 255, 0.15);
                    --cascade-text: #ECECEE;
                    --cascade-subtext: rgba(255, 255, 255, 0.55);
                    --cascade-shadow: 0 20px 40px rgba(0, 0, 0, 0.25);
                }
                ${shimmerCSS}
            `}</style>

            {/* Window Header */}
            <header style={{ alignItems: "center", borderBottom: "1px solid var(--cascade-line)", display: "flex", height: 40, padding: "0 16px", gap: 8 }}>
                {["#FF5F57", "#FEBC2E", "#28C840"].map(c => <span key={c} style={{ background: c, borderRadius: 999, height: 12, width: 12, flexShrink: 0 }} />)}
            </header>

            {/* Loading Skeleton State */}
            <div
                style={{
                    display: "flex",
                    flex: 1,
                    padding: "clamp(16px, 4vw, 24px)",
                    gap: "clamp(12px, 3vw, 24px)",
                    transition: "opacity 400ms",
                    opacity: loaded ? 0 : 1,
                    position: loaded ? "absolute" : "relative",
                    pointerEvents: loaded ? "none" : "auto",
                    width: "100%",
                    boxSizing: "border-box",
                    flexWrap: "wrap",
                }}
            >
                <aside style={{ display: "flex", flexDirection: "column", gap: 12, width: "100%", maxWidth: 160, flexShrink: 0 }}>
                    {[0, 100, 200, 300, 400].map((d, i) => (
                        <ShimmerBlock key={i} delay={d} height={14} width={`${80 - i * 5}%`} rounded={6} />
                    ))}
                </aside>

                <section style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: 16, flex: 1, width: "100%" }}>
                    {[300, 450, 600, 750].map((d, i) => (
                        <div key={i} style={{ background: "var(--cascade-panel)", border: "1px solid var(--cascade-line)", borderRadius: 12, padding: 16, display: "flex", flexDirection: "column", gap: 12 }}>
                            <ShimmerBlock delay={d} height={32} width={32} rounded={8} />
                            <ShimmerBlock delay={d + 100} height={12} width="80%" />
                            <ShimmerBlock delay={d + 200} height={12} width="60%" />
                        </div>
                    ))}
                </section>
            </div>

            {/* Loaded State */}
            {loaded && (
                <div style={{ position: "absolute", inset: 0, top: 40, display: "flex", alignItems: "center", justifyContent: "center", padding: 24, boxSizing: "border-box", animation: "cascadeFadeUp 500ms ease-out forwards" }}>
                    <div style={{ textAlign: "center", background: "var(--cascade-panel)", padding: "clamp(20px, 5vw, 32px) clamp(24px, 6vw, 48px)", borderRadius: 16, border: "1px solid var(--cascade-line)", width: "100%", maxWidth: 400, boxSizing: "border-box" }}>
                        <h2 style={{ margin: "0 0 8px 0", fontSize: 18, fontWeight: 500 }}>Dashboard Ready</h2>
                        <p style={{ margin: 0, color: "var(--cascade-subtext)", fontSize: 14 }}>All metrics have been synced successfully.</p>
                        <button
                            onClick={() => setCycle(c => c + 1)}
                            style={{ marginTop: 24, background: "var(--cascade-skeleton-hi)", border: 0, color: "var(--cascade-text)", padding: "8px 16px", borderRadius: 6, cursor: "pointer", fontWeight: 500, fontSize: 14 }}
                        >
                            Replay Animation
                        </button>
                    </div>
                </div>
            )}
        </main>
    )
}

// ==========================================
// Main Export for page.tsx
// ==========================================
export default function LoadingAnimationsDemo() {
    return (
        <div
            className="cascade-demo-wrapper"
            style={{
                display: "flex",
                flexDirection: "column",
                gap: 48,
                padding: "clamp(16px, 5vw, 48px)",
                background: "var(--demo-bg)",
                minHeight: "100vh",
                width: "100%",
                alignItems: "center",
                justifyContent: "center",
                boxSizing: "border-box",
            }}
        >
            <style>{`
                .cascade-demo-wrapper {
                    --demo-bg: #e4e4e7;
                }
                .dark .cascade-demo-wrapper,
                [data-theme="dark"] .cascade-demo-wrapper {
                    --demo-bg: #09090b;
                }
            `}</style>
            <div style={{ width: "100%", maxWidth: 720, display: "flex", flexDirection: "column", gap: 48 }}>
                <CascadeDashboard />
            </div>
        </div>
    )
}

